import sys
from itertools import combinations

def count_distinct_prime_factors(n):
    if n < 2:
        return 0
    count = 0
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            count += 1
            while n % factor == 0:
                n //= factor
        factor += 1
    if n > 1:
        count += 1
    return count

def max_revenue(N, S):
    max_rev = 0
    for i in range(1, 1 << N):
        sums = [0] * N
        for j in range(N):
            if i & (1 << j):
                sums[j] = sum(S[k] for k in range(N) if i & (1 << k))
        rev = sum(count_distinct_prime_factors(s) for s in sums)
        max_rev = max(max_rev, rev)
    return max_rev

